mapper.select:
SELECT r.id AS return_id, r.return_no, r.order_id, so.order_no,
       r.customer_id, so.customer_name_snapshot AS customer_name,
       r.status, r.reason, r.decision_reason, r.approved_amount,
       r.approved_at, r.rejected_at, r.cancelled_at, r.version, r.deleted,
       r.created_at, r.updated_at, r.created_by, r.updated_by
FROM order_return r
LEFT JOIN sales_order so ON so.id = r.order_id AND so.deleted = FALSE
WHERE r.deleted = FALSE



        AND so.seller_id IN
        #{scopeId}

    AND FALSE

AND r.customer_id=#{query.customerId}
AND r.status=#{query.status}
AND r.order_id=#{query.orderId}

    AND (r.return_no ILIKE '%' || #{query.keyword} || '%'
      OR so.order_no ILIKE '%' || #{query.keyword} || '%'
      OR so.customer_name_snapshot ILIKE '%' || #{query.keyword} || '%')

AND r.created_at >= #{query.startTime}
AND r.created_at < #{query.endTime}
ORDER BY r.created_at DESC,r.id DESC
